//! Event-label integration control; never replaces the ordinary statistical gate.
mod io;
use quantum_ecc::{circuit::{Op,OperationType as K},sim::Simulator};
use sha3::{Shake256,Sha3_256,Digest,digest::{Update,ExtendableOutput,XofReader}};
use std::collections::BTreeSet;
const NO:u64=u64::MAX;
fn rng(label:&str,batch:u64)->impl XofReader{let mut h=Shake256::default();Update::update(&mut h,label.as_bytes());Update::update(&mut h,&batch.to_le_bytes());h.finalize_xof()}
fn word(r:&mut impl XofReader)->u64{let mut x=[0;8];r.read(&mut x);u64::from_le_bytes(x)}
fn hash(v:&[Op])->String{let mut h=Sha3_256::new();for o in v{for x in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{Digest::update(&mut h,x.to_le_bytes());}}format!("{:x}",h.finalize())}
fn dims(v:&[Op])->(usize,usize){let q=v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;let b=v.iter().flat_map(|o|[o.c_condition.0,o.c_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;(q,b)}
struct Bytes{data:Vec<u8>,at:usize}
impl XofReader for Bytes{fn read(&mut self,out:&mut[u8]){let end=self.at.checked_add(out.len()).unwrap();assert!(end<=self.data.len(),"unexpected RNG consumption");out.copy_from_slice(&self.data[self.at..end]);self.at=end;}}
fn validate_map(map:&[u32],count:usize){assert_eq!(map.len(),count);let mut seen=vec![false;count];for &m in map{assert!((m as usize)<count);assert!(!seen[m as usize]);seen[m as usize]=true;}assert!(seen.iter().all(|x|*x));}
fn permute_random_bytes(original:&[u8],map:&[u32])->Vec<u8>{validate_map(map,map.len());assert_eq!(original.len(),map.len()*8+64);let mut out=Vec::with_capacity(original.len());for &i in map{out.extend_from_slice(&original[i as usize*8..i as usize*8+8]);}out.extend_from_slice(&original[map.len()*8..]);out}
fn run(v:&[Op],bytes:Vec<u8>,input:&[(bool,usize,u64)],phase:u64)->(Vec<u64>,Vec<u64>,u64,u64,[u8;64]){let(q,b)=dims(v);let mut r=Bytes{data:bytes,at:0};let mut s=Simulator::new(q,b,&mut r);s.phase=phase;for &(is_q,i,x)in input{if is_q{s.qubits[i]=x}else{s.bits[i]=x}}s.apply_iter(v.iter());let state=(s.qubits.clone(),s.bits.clone(),s.phase,s.stats.toffoli_gates);drop(s);let mut after=[0;64];r.read(&mut after);assert_eq!(r.at,r.data.len());(state.0,state.1,state.2,state.3,after)}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),7);let old=io::load_ops(&a[1]);let reordered=io::load_ops(&a[2]);let colored=io::load_ops(&a[3]);let map_raw=std::fs::read(&a[4]).unwrap();assert_eq!(&map_raw[..8],b"RNGPERM1");let count=u64::from_le_bytes(map_raw[8..16].try_into().unwrap())as usize;assert_eq!(map_raw.len(),80+4*count);let input_hash=hash(&old);assert_eq!(&map_raw[16..80],input_hash.as_bytes());let map:Vec<_>=map_raw[80..].chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();validate_map(&map,count);
 let mut ordinal=vec![u32::MAX;old.len()];let mut k=0;for(i,o)in old.iter().enumerate(){if matches!(o.kind,K::R|K::Hmr){ordinal[i]=k;k+=1;}}assert_eq!(k as usize,count);assert_eq!(old.len(),reordered.len());let perm_raw=std::fs::read(&a[5]).unwrap();assert_eq!(perm_raw.len(),old.len()*8);let mut seen=vec![false;old.len()];let mut event=0;for(new,raw)in perm_raw.chunks_exact(8).enumerate(){let index=u64::from_le_bytes(raw.try_into().unwrap())as usize;assert!(index<old.len());assert!(!seen[index]);seen[index]=true;assert_eq!(old[index],reordered[new],"operation/permutation mismatch");if ordinal[index]!=u32::MAX{assert_eq!(map[event],ordinal[index]);event+=1;}}assert_eq!(event,count);assert!(seen.iter().all(|x|*x));drop(ordinal);drop(seen);drop(perm_raw);
 assert_eq!(colored.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).count(),count);let registered:BTreeSet<_>=old.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=NO).map(|o|o.q_target.0 as usize).collect();let mut rows=vec![];
 for batch in 0..8{let mut input_rng=rng("mr-channel-control-uniform-raw-inputs-20261019",batch);let mut input=vec![];let mut seen=BTreeSet::new();for o in &old{if o.kind==K::AppendToRegister{for(q,i)in [(true,o.q_target.0),(false,o.c_target.0)]{if i!=NO&&seen.insert((q,i)){input.push((q,i as usize,word(&mut input_rng)));}}}}let phase=word(&mut input_rng);let mut physical=rng("mr-channel-control-event-labeled-RNG-20261019",batch);let mut original=vec![0;count*8+64];physical.read(&mut original);let mapped=permute_random_bytes(&original,&map);let x=run(&old,original,&input,phase);let y=run(&reordered,mapped.clone(),&input,phase);assert_eq!(x,y,"full transcript under event-label bijection");let z=run(&colored,mapped,&input,phase);assert_eq!(x.1,z.1,"original classical bits");assert_eq!(x.2,z.2,"phase");assert_eq!(x.3,z.3,"Toffolis");assert_eq!(x.4,z.4,"continuation after all events");for &q in &registered{assert_eq!(x.0[q],z.0[q],"registered output");}let mut xx:Vec<_>=x.0.iter().enumerate().filter(|(q,_)|!registered.contains(q)).map(|(_,x)|*x).collect();let mut zz:Vec<_>=z.0.iter().enumerate().filter(|(q,_)|!registered.contains(q)).map(|(_,x)|*x).collect();let width=xx.len().max(zz.len());xx.resize(width,0);zz.resize(width,0);xx.sort_unstable();zz.sort_unstable();assert_eq!(xx,zz,"scratch-state multiset");rows.push(serde_json::json!({"batch":batch,"shots":64,"complete_event_label_transcript_equal":true,"colored_outputs_bits_phase_Toffolis_and_event_continuation_equal":true}));}
 let result=serde_json::json!({"status":"PROTECTED_SIMULATOR_EVENT_LABEL_BIJECTION_CONTROL_PASS","scope":"Tool integration on 512 raw assignments; mapped event outcomes, not ordinary physical-RNG coupling, not a statistical failure gate or score","input_sha3_256":input_hash,"reordered_sha3_256":hash(&reordered),"colored_sha3_256":hash(&colored),"rng_map_sha3_256":format!("{:x}",Sha3_256::digest(&map_raw)),"rng_events":count,"changed_event_positions":map.iter().enumerate().filter(|(i,x)|*i!=**x as usize).count(),"original_Q":dims(&old).0,"colored_Q":dims(&colored).0,"rows":rows});std::fs::write(&a[6],serde_json::to_string_pretty(&result).unwrap()).unwrap();println!("eight event-label protected transcript controls pass");}
#[cfg(test)]mod tests{
 use super::*;use quantum_ecc::circuit::{QubitId,BitId};
 #[test]fn mapping_reorders_whole_words_and_preserves_continuation(){let data:Vec<_>=(0..80).collect();let out=permute_random_bytes(&data,&[1,0]);assert_eq!(&out[..8],&data[8..16]);assert_eq!(&out[8..16],&data[..8]);assert_eq!(&out[16..],&data[16..]);}
 #[test]#[should_panic]fn duplicate_map_rejected(){validate_map(&[0,0],2);}
 #[test]#[should_panic]fn out_of_range_map_rejected(){validate_map(&[0,2],2);}
 #[test]#[should_panic]fn missing_map_rejected(){validate_map(&[0],2);}
 #[test]fn disjoint_measurements_match_with_mapped_outcomes(){let mut x=Op::empty();x.kind=K::Hmr;x.q_target=QubitId(0);x.c_target=BitId(0);let mut y=x;y.q_target=QubitId(1);y.c_target=BitId(1);let a=vec![x,y];let b=vec![y,x];let mut bytes=vec![0;80];bytes[..8].copy_from_slice(&u64::MAX.to_le_bytes());let inputs=[(true,0,u64::MAX),(true,1,0)];let old=run(&a,bytes.clone(),&inputs,0);let physical=run(&b,bytes.clone(),&inputs,0);assert_ne!(old,physical);let mapped=run(&b,permute_random_bytes(&bytes,&[1,0]),&inputs,0);assert_eq!(old,mapped);}
}
